{"command": "cat > /etc/nginx/conf.d/api.conf << 'EOF'
# Cache zone configuration
proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=apicache:10m inactive=1000s;

server {
    listen 80;
    server_name localhost;

    # Redirects
    location = /sunny {
        return 302 /api/service1;
    }

    location = /woods {
        return 302 /api/service2;
    }

    location = /stream {
        return 302 /api/service3;
    }

    # Proxy routes with caching
    location /api/service1 {
        proxy_pass http://localhost:3000/data;
        proxy_cache apicache;
        proxy_cache_valid 200 1000s;
        proxy_cache_key $scheme$host$request_uri;
        add_header X-Cache-Status $upstream_cache_status;
    }

    location /api/service2 {
        proxy_pass http://localhost:3001/data;
        proxy_cache apicache;
        proxy_cache_valid 200 1000s;
        proxy_cache_key $scheme$host$request_uri;
        add_header X-Cache-Status $upstream_cache_status;
    }

    location /api/service3 {
        proxy_pass http://localhost:3002/data;
        proxy_cache apicache;
        proxy_cache_valid 200 1000s;
        proxy_cache_key $scheme$host$request_uri;
        add_header X-Cache-Status $upstream_cache_status;
    }

    location /api/service4 {
